-- =============================================================================
-- UPDATE TRIGGER (for updated_at)
-- =============================================================================

-- PostgreSQL: Create a trigger function for auto-updating updated_at
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply to each table:
-- CREATE TRIGGER set_updated_at
